import { serve, upgradeWebSocket } from "std/http"

const server = await serve({ port: 0 }, async (req) => {
  const up = upgradeWebSocket(req)
  up.socket.onmessage = (e) => up.socket.send(e.data)   // echo
  return up.response
})
const done = Promise.withResolvers<bool, Error>()
const ws = new WebSocket(`ws://127.0.0.1:${server.addr.port}/`)
ws.onopen = (e) => ws.send("hello")
ws.onmessage = (e) => {
  println(`echo: ${e.data}`)   // echo: hello
  ws.close()
}
ws.onclose = (e) => done.resolve(true)
await done.promise
await server.shutdown()

import { serve, upgradeWebSocket } from "std/http"

const server = await serve({ port: 0 }, async (req) => {
  const up = try? upgradeWebSocket(req)   // throws a TypeError for a plain request
  if (up == null) {
    return new Response("WebSocket only", { status: 400 })
  }
  const socket = up.socket
  socket.onmessage = (e) => socket.send(`got ${e.data}`)
  return up.response
})
const res = await fetch(`http://127.0.0.1:${server.addr.port}/`)
println(`${res.status} ${await res.text()}`)   // 400 WebSocket only
const done = Promise.withResolvers<bool, Error>()
const ws = new WebSocket(`ws://127.0.0.1:${server.addr.port}/`)
ws.onopen = (e) => ws.send("hi")
ws.onmessage = (e) => {
  println(e.data)   // got hi
  ws.close()
}
ws.onclose = (e) => done.resolve(true)
await done.promise
await server.shutdown()

