const re = /(\w+)=(\d+)/g
const s = "a=1 b=22"
let m = re.exec(s)
while (m != null) {
  println(`${m[1]} -> ${m[2]} at ${m.index}`)
  m = re.exec(s)
}
// Prints:
// a -> 1 at 0
// b -> 22 at 4

const m = /(\d+)-(\d+)?/d.exec("id 12-")
if (m != null) {
  const ix = m.indices
  if (ix != null) {
    println(`${ix.length} ${ix[0]:?} ${ix[1]:?} ${ix[2]:?}`)   // 3 [3, 6] [3, 5] null
  }
}

// They usually come from a `d`-flag match; they can also be built directly.
const ix = new RegExpIndices([[0, 2], null], null)
println(`${ix[0]:?} ${ix[1]:?}`)   // [0, 2] null

const m = /(?<year>\d{4})-(\d{2})/.exec("due 2024-03")
if (m != null) {
  println(m[0])                       // 2024-03
  println(m[2])                       // 03
  println(m.index)                    // 4
  println(m.groups?.get("year"))      // 2024
}

const m = /a(?<b>b+)/d.exec("xabb")
if (m != null) {
  println(`${m.indices?.[0]:?} ${m.indices?.[1]:?}`)    // [1, 4] [2, 4]
  println(`${m.indices?.groups?.get("b"):?}`)           // [2, 4]
}

// Matches usually come from `exec` or `string.match`; one can also be built directly.
const m = new RegExpMatch(["ab", "b"], 3, "xxxab", null)
println(m[0])      // ab
println(m.index)   // 3

const m = /(\w+)@(\w+)/.exec("mail ann@home")
if (m != null) {
  println(m.length)   // 3
}

const m = /(\d+)x(\d+)?/.exec("size 640x")
if (m != null) {
  const parts = m.toArray()
  println(parts.length)                               // 3
  println(parts.map(s => s ?? "(none)").join(", "))   // 640x, 640, (none)
}

